# **Q3 (b) – Add Two Distances (Constructor Overloading + Friend Function)**

### **Very Simple Code**
```cpp
#include <iostream>
using namespace std;

class Distance {
    int meters;
public:
    Distance() { meters = 0; }          // default constructor
    Distance(int m) { meters = m; }     // parameterized

    friend Distance add(Distance, Distance);
    void show() { cout << meters << " meters\n"; }
};

Distance add(Distance d1, Distance d2) {
    Distance temp;
    temp.meters = d1.meters + d2.meters;
    return temp;
}

int main() {
    Distance d1(5), d2(7);
    Distance d3 = add(d1, d2);

    cout << "Total = ";
    d3.show();
}
```

