# **Q4 (a) – Overload < and > Operators**

### **Easy Program**
```cpp
#include <iostream>
using namespace std;

class Num {
    int x;
public:
    Num(int a) { x = a; }

    bool operator<(Num n) {
        return x < n.x;
    }

    bool operator>(Num n) {
        return x > n.x;
    }
};

int main() {
    Num a(10), b(20);

    if(a < b) cout << "a is smaller\n";
    if(b > a) cout << "b is larger\n";
}
```

