# ✅ **Super Simple Exam-Ready Code**

```cpp
#include <iostream>
using namespace std;

class Distance {
    int feet;
    int inches;

public:
    Distance() {        // default constructor
        feet = 0;
        inches = 0;
    }

    Distance(int f, int i) {   // parameterized constructor
        feet = f;
        inches = i;
    }

    friend Distance addDist(Distance, Distance);  // friend function

    void show() {
        cout << feet << " feet " << inches << " inches\n";
    }
};

// Friend function definition
Distance addDist(Distance d1, Distance d2) {
    Distance temp;

    temp.feet = d1.feet + d2.feet;
    temp.inches = d1.inches + d2.inches;

    if (temp.inches >= 12) {   // convert inches to feet
        temp.feet += temp.inches / 12;
        temp.inches = temp.inches % 12;
    }

    return temp;
}

int main() {
    Distance d1(5, 8);   // 5 feet 8 inches
    Distance d2(3, 10);  // 3 feet 10 inches

    Distance d3 = addDist(d1, d2);

    cout << "Total Distance = ";
    d3.show();
}
```

