# ⭐ **VERY SIMPLE C++ PROGRAM (Exam Ready)**

```cpp
#include <iostream>
using namespace std;

// Class 1: Internal Exam
class InternalExam {
public:
    int internalMarks;

    void getdata() {
        cout << "Enter Internal Exam Marks: ";
        cin >> internalMarks;
    }

    void displaydata() {
        cout << "Internal Exam Marks: " << internalMarks << endl;
    }
};

// Class 2: Final Exam
class FinalExam {
public:
    int finalMarks;

    void getdata() {
        cout << "Enter Final Exam Marks: ";
        cin >> finalMarks;
    }

    void displaydata() {
        cout << "Final Exam Marks: " << finalMarks << endl;
    }
};

// Child class using MULTIPLE INHERITANCE
class Result : public InternalExam, public FinalExam {
public:
    float average;

    void calculate() {
        average = (internalMarks + finalMarks) / 2.0;
    }

    void displayResult() {
        cout << "Final Average Result = " << average << endl;
    }
};

int main() {
    Result r;

    // Calling parent class functions explicitly
    r.InternalExam::getdata();
    r.FinalExam::getdata();

    r.calculate();

    cout << "\n--- RESULT DETAILS ---\n";
    r.InternalExam::displaydata();
    r.FinalExam::displaydata();
    r.displayResult();

    return 0;
}
```

